-- Bloc-level trade embargoes against other states.

CREATE TABLE IF NOT EXISTS "bloc_embargoes" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "bloc_id" integer NOT NULL REFERENCES "blocs"("id") ON DELETE CASCADE,
  "target_state_id" integer NOT NULL REFERENCES "states"("id") ON DELETE CASCADE,
  "declared_by" text NOT NULL REFERENCES "account"("id") ON DELETE CASCADE,
  "reason" text NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_bloc_embargo" ON "bloc_embargoes" ("bloc_id", "target_state_id");
